const body = $input.first().json.body || {};
const input = body.input || {};

let pkgs = [];
if (Array.isArray(input.packages)) {
  pkgs = input.packages;
} else if (input.dependencies && typeof input.dependencies === 'object') {
  // A package.json dependencies block, pasted whole. Ranges are stripped to a
  // concrete version: OSV matches versions, not ranges, and "^4.17.20" would
  // silently match nothing and report a clean scan.
  pkgs = Object.entries(input.dependencies).map(([name, range]) => ({
    name,
    version: String(range).replace(/^[\^~>=<\s]+/, ''),
    ecosystem: input.ecosystem || 'npm',
  }));
}

pkgs = pkgs.filter((p) => p && p.name && p.version).slice(0, 100);
if (!pkgs.length) {
  throw new Error('Send {"input":{"packages":[{"name","version","ecosystem"}]}} or {"input":{"dependencies":{...}}}');
}

return [{ json: {
  pkgs,
  queries: pkgs.map((p) => ({
    package: { name: p.name, ecosystem: p.ecosystem || 'npm' },
    version: String(p.version),
  })),
} }];

const item = $input.first().json;
const raw = item.data ?? item;

let osv;
try {
  osv = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error('OSV did not return JSON: ' + String(raw).slice(0, 300));
}

const pkgs = $('Build queries').first().json.pkgs;

// A scanner that cannot tell "found nothing" from "the lookup never ran" is
// worse than no scanner at all, because it sells a clean bill of health for a
// question it failed to ask. OSV answers querybatch with exactly one result per
// query, in order. Anything else -- an error body, a rate limit, a truncated
// response -- means we do not know, and the only honest move is to fail loudly
// rather than return zero findings that look identical to a real all-clear.
const results = osv.results;
if (!Array.isArray(results) || results.length !== pkgs.length) {
  throw new Error(
    'OSV returned ' + (Array.isArray(results) ? results.length : 'no') +
    ' result(s) for ' + pkgs.length + ' query/queries. Refusing to report a clean scan. ' +
    'Response was: ' + JSON.stringify(osv).slice(0, 300)
  );
}

const findings = [];
pkgs.forEach((p, i) => {
  const vulns = (results[i] && results[i].vulns) || [];
  if (vulns.length) {
    findings.push({
      package: p.name,
      version: p.version,
      advisories: vulns.map((v) => ({ id: v.id, url: 'https://osv.dev/vulnerability/' + v.id })),
    });
  }
});

// `scanned` and `checkedAt` are part of the product, not decoration: what is
// being bought is a dated statement about a specific set of versions.
return [{ json: { output: {
  scanned: pkgs.length,
  vulnerable: findings.length,
  findings,
  source: 'osv.dev',
  checkedAt: new Date().toISOString(),
} } }];
